//! 🧪️ The concrete sealed compiler frame uses genuine caller loans and exact frame-only allocator receipts.
use super::*;
use super::super::{Node,Fields};
use crate::native_caller::{NativeFrameCaller,NativeFrameRootPolicyV1};
use semio_framework_job::{OperationId,Generation,OriginalContiguousJobBytes,OriginalJobBytesReturnRegistry};
use semio_framework_plugin_interpreter_runtime::OwnedRuntime;
fn clock()->Option<u64>{Some(1)}
fn wake_return(){}
static RETURNS:OriginalJobBytesReturnRegistry<64>=OriginalJobBytesReturnRegistry::with_return_wake(wake_return);
fn caller(id:u64)->NativeFrameCaller{let policy:NativeFrameRootPolicyV1=serde_json::from_str(include_str!("../../../../../../⌨️native-entrypoint/🎟️launch/🔣️.json")).map(|value:serde_json::Value|serde_json::from_value(value["compilerTask"].clone()).unwrap()).unwrap();NativeFrameCaller::new(OperationId(id),Generation(2),clock,policy).unwrap()}
fn admit_roots(node:&mut Node,slot:&Slot){for _ in 0..64{if node.caller.ready(){return}node.pump(slot);}panic!("actual compiler fixture source roots did not admit")}
#[test]
fn renderer_compiler_task_actual_frame_loan_and_original_backing_return_match_allocator(){
 let runtime=Arc::new(GuestRuntimes::Owned(OwnedRuntime::new(clock)));
 let supplier_slot=Slot::empty();let mut supplier=Node::new(caller(735));admit_roots(&mut supplier,&supplier_slot);
 let mut backing=None;for _ in 0..8{let call=supplier.caller.dispatch_step(|cx|OriginalContiguousJobBytes::admit(0,&mut backing,cx));supplier.accept(call);if backing.as_ref().is_some_and(OriginalContiguousJobBytes::complete){break}}assert!(backing.as_ref().unwrap().complete());
 let mut reservation=None;let call=supplier.caller.dispatch_step(|cx|{reservation=RETURNS.reserve(cx)?;Ok(reservation.is_some())});assert_eq!(supplier.accept(call),Some(true));let mut bytes=None;let call=supplier.caller.dispatch_step(|cx|reservation.as_mut().unwrap().publish(&mut backing,&mut bytes,cx));assert_eq!(supplier.accept(call),Some(true));drop(reservation);
 let (index,mut state)=SLOTS.iter().enumerate().find_map(|(index,slot)|slot.node.try_lock().ok().filter(|node|node.is_none()).map(|node|(index,node))).expect("compiler native law has one vacant fixed process slot");let slot=&SLOTS[index];let generation=slot.generation.load(Ordering::Relaxed).checked_add(1).unwrap();assert!(generation<=(usize::MAX>>6)as u64);slot.generation.store(generation,Ordering::Release);slot.detached.store(false,Ordering::Release);slot.compiler_cancelled.store(false,Ordering::Release);slot.compiler_wake.store(false,Ordering::Release);slot.notify_client.store(false,Ordering::Release);unsafe{assert!((&*slot.compiler_inputs.get()).terminal());*slot.compiler_output.get()=Output::empty();assert!((&*slot.fields.get()).empty_owner());*slot.fields.get()=Fields::empty();}*state=Some(Node::new(caller(736)));let node=state.as_mut().unwrap();admit_roots(node,slot);
 let input=super::super::CreateAppBorrowed{path:std::path::Path::new("compiler/native/frame.wasm"),plugin:"compiler.fixture",app:"app",schema:"schema"};for _ in 0..5{node.receive(slot,input);}assert!(slot.published.load(Ordering::Acquire));assert_ne!(node.caller.original_clock_binding(),supplier.caller.original_clock_binding());
 let before=node.caller.retained_spent();let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let call=node.caller.dispatch_step(|cx|admit(index,generation,&runtime,PackageHash([7;32]),&mut bytes,&mut node.compiler,cx));assert_eq!(node.accept(call),Some(true));node.compiler.as_mut().unwrap().committed=true;});let after=node.caller.retained_spent();assert_eq!(heap.requested_bytes,after.retained_capacity_bytes-before.retained_capacity_bytes);assert_eq!(heap.released_bytes,0);let born=heap.requested_bytes;assert!(born>=input.plugin.len());assert!(bytes.is_none());
 let waker=unsafe{Waker::from_raw(Ticket{index,generation}.raw())};let(_,wake_heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(waker.clone()));assert_eq!((wake_heap.requested_bytes,wake_heap.released_bytes),(0,0));drop(waker);
 let call=node.caller.dispatch_step(|cx|node.compiler.as_mut().unwrap().poll(cx));assert_eq!(node.accept(call),Some(Status::Pending));assert!(!node.caller.original_loans_are_returned());
 let mut released=0;for _ in 0..64{if node.compiler.as_ref().unwrap().terminal(){break}let before=node.caller.retained_spent();let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let call=node.caller.dispatch_cleanup_step(|cx|node.compiler.as_mut().unwrap().close(Some(&runtime),cx));assert!(node.accept(call).is_some());});let after=node.caller.retained_spent();assert_eq!(heap.requested_bytes,0);assert_eq!(heap.released_bytes,after.released_bytes-before.released_bytes);released+=heap.released_bytes;}assert!(node.compiler.as_ref().unwrap().terminal());assert_eq!(released,born);assert!(node.caller.original_loans_are_returned());let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(node.compiler.take()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 for _ in 0..64{if supplier.caller.original_loans_are_returned(){break}let call=supplier.caller.dispatch_cleanup_step(|cx|RETURNS.close_returned_step(cx));assert!(supplier.accept(call).is_some());}assert!(supplier.caller.original_loans_are_returned());slot.detached.store(true,Ordering::Release);for _ in 0..128{if node.closed{break}node.pump(slot);}assert!(node.closed);state.take();slot.published.store(false,Ordering::Release);supplier_slot.detached.store(true,Ordering::Release);for _ in 0..128{if supplier.closed{break}supplier.pump(&supplier_slot);}assert!(supplier.closed);println!("[DEBUG] concrete unpolled compiler frame/package birth and staged close equal actual allocator receipts; genuine distinct supplier backing and task loans return before both original roots; opaque compiler backend was not polled");
}
